package com.ferreteriahuaman.integration;
import com.ferreteriahuaman.service.*;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.dto.SaleModels.*;import com.ferreteriahuaman.dto.SaleModels.Details;import com.ferreteriahuaman.dto.SaleModels.Line;import com.ferreteriahuaman.dto.CashModels.Open;import com.ferreteriahuaman.dto.ProductModels.*;import com.ferreteriahuaman.dto.PurchaseModels.*;import com.ferreteriahuaman.security.AuthModels.Identity;import com.ferreteriahuaman.security.AuthFailure;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="HUAMAN_DB_INTEGRATION",matches="true")
class SaleDatabaseTest {
 @Autowired InventoryService inventory;@Autowired SaleService service;@Autowired ProductService products;@Autowired PurchaseService purchases;@Autowired CashService cash;@Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;Identity actor;long category;String unique;BigDecimal n(String s){return new BigDecimal(s);}
 @BeforeEach void setup(){Assumptions.assumeTrue(jdbc.queryForObject("select count(*) from huaman.caja_diaria where estado_caja='ABIERTA' or fecha=timezone('America/Lima',now())::date",Long.class)==0,"No interferir con cajas reales");var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusMinutes(30));unique="INTEGRACION_"+UUID.randomUUID().toString().substring(0,8).toUpperCase();category=catalog.createCategory(actor,"INTEGRATION_ROLLBACK",new com.ferreteriahuaman.dto.CatalogModels.CategoryInput(unique,null,null)).id();cash.open(actor,"INTEGRATION_ROLLBACK",new Open(n("0"),null,UUID.randomUUID()));jdbc.update("update huaman.parametro_sistema set valor='Negocio de integración' where clave='NEGOCIO.RAZON_SOCIAL'");jdbc.update("update huaman.parametro_sistema set valor='20123456789' where clave='NEGOCIO.RUC'");jdbc.update("update huaman.parametro_sistema set valor='Dirección temporal 123' where clave='NEGOCIO.DIRECCION'");}
 Product product(String mode,String unitCode){long unit=jdbc.queryForObject("select id_unidad from huaman.unidad_medida where codigo_sunat=?",Long.class,unitCode);return products.create(actor,"INTEGRATION_ROLLBACK",new ProductInput(unique+mode.substring(0,1),"Producto "+mode,null,category,unit,true,n("0.001"),n("0.001"),mode,n("0"),null,"Base",n("10"),null));}
 long presentation(Product p){return products.details(actor,p.id()).presentaciones().getFirst().id();}
 long id(Details d){return ((Number)d.venta().get("id")).longValue();}
 Details create(long presentation,String qty,int pieces,String type,Long client){return service.create(actor,"INTEGRATION_ROLLBACK",new Create(client,type,true,UUID.randomUUID(),List.of(new Line(presentation,n(qty),pieces))));}
 long series(String type){return jdbc.queryForObject("select min(id_serie) from huaman.serie_comprobante where tipo_comprobante=? and estado='A'",Long.class,type);}
 Confirm request(Details d,List<Payment> payments,List<Assignment> assignments){return new Confirm(series(d.venta().get("tipo").toString()),LocalDateTime.parse(d.venta().get("version").toString()),payments,assignments);}
 Payment pay(String medium,String amount,String received,String operation){return new Payment(medium,n(amount),received==null?null:n(received),operation,null,null);}
 @Test void fractionalSaleCalculatesPricesStockCashReceiptAndIdempotency(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("10"),n("1"),UUID.randomUUID(),List.of()));var input=new Create(null,"B",true,UUID.randomUUID(),List.of(new Line(presentation(p),n("0.100"),1)));var d=service.create(actor,"INTEGRATION_ROLLBACK",input);assertThat(service.create(actor,"INTEGRATION_ROLLBACK",input).venta().get("id")).isEqualTo(id(d));assertThat(d.venta().get("total")).isEqualTo("1.00");var request=request(d,List.of(pay("EFECTIVO","1","2",null)),List.of());var done=service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request);assertThat(done.venta().get("estado")).isEqualTo("CONFIRMADA");assertThat(done.comprobante().get("documento")).isNull();assertThat(done.pagos().getFirst().get("vuelto")).isEqualTo("1.00");assertThat(service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request).comprobante().get("id")).isEqualTo(done.comprobante().get("id"));assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("9.900000");assertThat(cash.current().caja().efectivo()).isEqualTo("1.00");assertThat(cash.current().caja().ventasPendientes()).isZero();jdbc.execute("set constraints all immediate");}
 @Test void wholesaleAndSplitPaymentAreCalculatedByDatabase(){var p=product("GRANEL","KGM");long pres=presentation(p);products.saveWholesale(actor,"INTEGRATION_ROLLBACK",p.id(),pres,null,new WholesaleInput(n("12"),n("8"),null));purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("100"),n("1"),UUID.randomUUID(),List.of()));var d=create(pres,"12",1,"N",null);assertThat(d.lineas().getFirst().get("origen")).isEqualTo("MAYORISTA");assertThat(d.venta().get("total")).isEqualTo("96.00");service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("EFECTIVO","50","50",null),pay("YAPE","46",null,"123456789")),List.of()));assertThat(cash.current().caja().yape()).isEqualTo("46.00");jdbc.execute("set constraints all immediate");}
 @Test void debitPaymentKeepsOnlyOptionalLastFourDigits(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("10"),n("1"),UUID.randomUUID(),List.of()));var d=create(presentation(p),"1",1,"N",null);var payment=new Payment("DEBITO",n("10"),null,"OPERACION-1","Visa","4512");var result=service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(payment),List.of()));assertThat(result.pagos().getFirst().get("ultimosCuatro")).isEqualTo("4512");assertThat(cash.current().caja().debito()).isEqualTo("10.00");}
 @Test void intactBagRequiresPhysicalAssignmentAndPreservesReconciliation(){var p=product("ENVASES","KGM");var bag=products.savePresentation(actor,"INTEGRATION_ROLLBACK",p.id(),null,new PresentationInput("Bolsa",null,n("50"),true,false,n("1"),n("1"),n("300"),null));purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("50"),n("1"),UUID.randomUUID(),List.of(new PhysicalUnit(unique,"ENVASE",n("50"),bag.id()))));long unit=purchases.existences(p.id(),0,20).items().getFirst().id();var d=create(bag.id(),"1",1,"N",null);long line=((Number)d.lineas().getFirst().get("id")).longValue();service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("EFECTIVO","300","300",null)),List.of(new Assignment(line,unit,1,n("50")))));assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("0.000000");assertThat(purchases.existences(p.id(),0,20).items().getFirst().cantidadDisponible()).isEqualTo("0.000000");jdbc.execute("set constraints all immediate");}
 @Test void insufficientStockRejectsConfirmation(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("1"),n("1"),UUID.randomUUID(),List.of()));var d=create(presentation(p),"2",1,"N",null);assertThatThrownBy(()->service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("EFECTIVO","20","20",null)),List.of()))).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void draftsCanBeResumedAndDiscardedWithoutStockOrCashMovement(){var p=product("GRANEL","KGM");var d=create(presentation(p),"1",1,"N",null);assertThat(service.drafts(actor)).anyMatch(v->v.get("id").equals(id(d)));var discard=new Discard(UUID.randomUUID(),LocalDateTime.parse(d.venta().get("version").toString()),"Corrección de borrador");service.discard(actor,"INTEGRATION_ROLLBACK",id(d),discard);assertThat(service.discard(actor,"INTEGRATION_ROLLBACK",id(d),discard).venta().get("estado")).isEqualTo("DESCARTADA");assertThat(cash.current().caja().ventasPendientes()).isZero();assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("0.000000");}
 @Test void anotherSellerCannotReadTheDraft(){var p=product("GRANEL","KGM");var d=create(presentation(p),"1",1,"N",null);var other=new Identity(actor.id()+999,"otro","Otro","Usuario","VEN",false,Set.of("VEN.VENDER"),UUID.randomUUID(),OffsetDateTime.now().plusMinutes(30));assertThatThrownBy(()->service.details(other,id(d))).isInstanceOf(AuthFailure.class);}
 @Test void changedPayloadCannotReuseCreationKey(){var p=product("GRANEL","KGM");var input=new Create(null,"N",true,UUID.randomUUID(),List.of(new Line(presentation(p),n("1"),1)));service.create(actor,"INTEGRATION_ROLLBACK",input);assertThatThrownBy(()->service.create(actor,"INTEGRATION_ROLLBACK",new Create(null,"N",true,input.clave(),List.of(new Line(presentation(p),n("2"),1))))).isInstanceOf(AuthFailure.class);}

 @Test void fiadoCreatesDebtWithoutCashMovement(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("10"),n("1"),UUID.randomUUID(),List.of()));String doc;do{doc=String.format("%08d",10000000+new java.security.SecureRandom().nextInt(90000000));}while(jdbc.queryForObject("select exists(select 1 from huaman.cliente where nro_documento=?)",Boolean.class,doc));var customer=customers.save(actor,"INTEGRATION_ROLLBACK",null,new com.ferreteriahuaman.dto.CustomerModels.Input("DNI",doc,unique,null,null,null,null));customers.credit(actor,"INTEGRATION_ROLLBACK",customer.id(),new com.ferreteriahuaman.dto.CustomerModels.Credit(n("100"),customer.version()));var d=create(presentation(p),"1",1,"N",customer.id());service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("CREDITO","10",null,null)),List.of()));assertThat(jdbc.queryForObject("select saldo from huaman.cuenta_por_cobrar where id_venta=?",BigDecimal.class,id(d))).isEqualByComparingTo("10");assertThat(new BigDecimal(cash.current().caja().efectivo())).isEqualByComparingTo("0");jdbc.execute("set constraints all immediate");}
 @Test void looseContentAllowsHundredGramsAfterOpeningBag(){var p=product("ENVASES","KGM");var bag=products.savePresentation(actor,"INTEGRATION_ROLLBACK",p.id(),null,new PresentationInput("Bolsa",null,n("50"),true,false,n("1"),n("1"),n("300"),null));purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("50"),n("1"),UUID.randomUUID(),List.of(new PhysicalUnit(unique,"ENVASE",n("50"),bag.id()))));long original=purchases.existences(p.id(),0,20).items().getFirst().id();inventory.transform(actor,"INTEGRATION_ROLLBACK",new com.ferreteriahuaman.dto.InventoryModels.Transformation(original,"ABRIR",List.of(),"Venta de contenido por peso",UUID.randomUUID()));long loose=purchases.existences(p.id(),0,20).items().stream().filter(u->u.condicion().equals("SUELTO")).findFirst().orElseThrow().id();var d=create(presentation(p),"0.1",1,"N",null);long line=((Number)d.lineas().getFirst().get("id")).longValue();service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("EFECTIVO","1","1",null)),List.of(new Assignment(line,loose,1,n("0.1")))));assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("49.900000");jdbc.execute("set constraints all immediate");}
 @Test void continuousPiecesAreAssignedToIdentifiedTramos(){var p=product("TRAMOS","MTR");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("6"),n("1"),UUID.randomUUID(),List.of(new PhysicalUnit(unique+"A","TRAMO",n("3"),null),new PhysicalUnit(unique+"B","TRAMO",n("3"),null))));var units=purchases.existences(p.id(),0,20).items();var d=create(presentation(p),"2",2,"N",null);long line=((Number)d.lineas().getFirst().get("id")).longValue();service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("EFECTIVO","20","20",null)),List.of(new Assignment(line,units.get(0).id(),1,n("1")),new Assignment(line,units.get(1).id(),2,n("1")))));assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("4.000000");jdbc.execute("set constraints all immediate");}
 @Test void activeOfferIsAppliedAndRecorded(){var p=product("GRANEL","KGM");long pres=presentation(p);purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("10"),n("1"),UUID.randomUUID(),List.of()));jdbc.update("insert into huaman.oferta(id_producto,id_presentacion,nombre,precio_oferta,fecha_inicio,fecha_fin) values(?,?,? ,7,timezone('America/Lima',now())::date,timezone('America/Lima',now())::date)",p.id(),pres,unique);var d=create(pres,"1",1,"N",null);assertThat(d.lineas().getFirst().get("origen")).isEqualTo("OFERTA");assertThat(d.venta().get("total")).isEqualTo("7.00");service.confirm(actor,"INTEGRATION_ROLLBACK",id(d),request(d,List.of(pay("EFECTIVO","7","7",null)),List.of()));jdbc.execute("set constraints all immediate");}
}
